package main

import (
	"fmt"

	"github.com/stretchr/objx"
)

func main() {
	// Wrap arbitrary JSON-like data.
	m := objx.MustFromJSON(`{
		"name": "Ada",
		"address": {"city": "London"},
		"tags": ["math", "computing"]
	}`)

	// Fluent, path-based reads with typed accessors and defaults.
	fmt.Println(m.Get("name").Str())
	fmt.Println(m.Get("address.city").Str())
	fmt.Println(m.Get("tags[1]").Str())
	fmt.Println(m.Get("age").Int(36)) // missing key -> default

	// Chainable writes (intermediate maps are created as needed).
	m.Set("address.country", "UK").Set("active", true)

	// Plain map[string]interface{} still available.
	var raw map[string]interface{} = m.Value().MSI()
	fmt.Println(raw["active"], m.Get("address.country").Str())
}
EOF
cat > main_test.go <<'EOF'
package main

import (
	"testing"

	"github.com/stretchr/objx"
)

func TestFluentAccess(t *testing.T) {
	m := objx.New(map[string]interface{}{
		"user": map[string]interface{}{"name": "Ada"},
	})

	if got := m.Get("user.name").Str(); got != "Ada" {
		t.Fatalf("user.name = %q, want %q", got, "Ada")
	}
	if got := m.Get("user.missing").Str("default"); got != "default" {
		t.Fatalf("default = %q, want %q", got, "default")
	}

	m.Set("user.lang", "en").Set("count", 2)
	if got := m.Get("user.lang").Str(); got != "en" {
		t.Fatalf("user.lang = %q, want %q", got, "en")
	}
	if got := m.Get("count").Int(); got != 2 {
		t.Fatalf("count = %d, want 2", got)
	}
}
EOF
